import{_ as a,o as l,c as i,aw as s}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Информация","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/js-promise/main/info.md","filePath":"wiki/dev-commit/js/js-promise/main/info.md"}'),t={name:"wiki/dev-commit/js/js-promise/main/info.md"};function o(n,e,r,c,p,h){return l(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="https://www.youtube.com/watch?v=1idOY3C1gYU" target="_blank" rel="noreferrer">https://www.youtube.com/watch?v=1idOY3C1gYU</a><a href="https://dev.to/lydiahallie/javascript-visualized-promises-async-await-5gke" target="_blank" rel="noreferrer">https://dev.to/lydiahallie/javascript-visualized-promises-async-await-5gke</a></p></div><ul><li><strong>Promise</strong> - специальный объект, который используются для обработки результатов асинхронных операций. Промис хранит своё состояние, текущий результат (если есть) и коллбэки</li><li><strong>Промисификация</strong> - обертка над асинхронным функционалом, возвращающая промис</li><li><strong>Чейнинг (chaining)</strong> - возможность стоить асинхронные цепочки из промисов .then…then…then, в каждый следующий then переходит результат от предыдущего</li></ul><h3 id="способ-использования" tabindex="-1">Способ использования <a class="header-anchor" href="#способ-использования" aria-label="Permalink to &quot;Способ использования&quot;">​</a></h3><ol><li>Код, которому нужно сделать что-то асинхронно, создаёт экземпляр объекта через new Promise и возвращает его</li><li>При создании new Promise автоматически запускается функция-аргумент, которая должна вызвать resolve(result) при успешном выполнении и reject(error) – при ошибке</li><li>Внешний код, получив promise, навешивает на него обработчики .then и .catch</li><li>По завершении процесса асинхронный код переводит promise в состояние fulfilled (с результатом) или rejected (с ошибкой). При этом автоматически вызываются соответствующие обработчики во внешнем коде .then и .catch</li></ol><h3 id="состояния-promise" tabindex="-1">Состояния Promise <a class="header-anchor" href="#состояния-promise" aria-label="Permalink to &quot;Состояния Promise&quot;">​</a></h3><ol><li>pending - ожидание (выполняется)</li><li>fulfilled - выполнено успешно</li><li>rejected - отклонено (выполнено с ошибкой)</li></ol><hr><h3 id="навешиваемые-коллбэки" tabindex="-1">Навешиваемые коллбэки <a class="header-anchor" href="#навешиваемые-коллбэки" aria-label="Permalink to &quot;Навешиваемые коллбэки&quot;">​</a></h3><ul><li>onFulfilled – срабатывают, когда promise в состоянии fulfilled</li><li>onRejected – срабатывают, когда promise в состоянии rejected</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">let</span><span style="color:#383A42;"> promise </span><span style="color:#0184BC;">=</span><span style="color:#A626A4;"> new</span><span style="color:#C18401;"> Promise</span><span style="color:#383A42;">(</span><span style="color:#A626A4;">function</span><span style="color:#383A42;">(resolve, reject) {</span></span>
<span class="line"><span style="color:#4078F2;">	resolve</span><span style="color:#383A42;">(arg) </span><span style="color:#A0A1A7;font-style:italic;">// =&gt; onFulfilled(arg) =&gt; .then(arg)  =&gt; Promise</span></span>
<span class="line"><span style="color:#4078F2;">	reject</span><span style="color:#383A42;">(arg)  </span><span style="color:#A0A1A7;font-style:italic;">// =&gt; onRejected(arg)  =&gt; .catch(arg) =&gt; Promise</span></span>
<span class="line"><span style="color:#383A42;">});</span></span></code></pre></div><h3 id="минусы-промисов" tabindex="-1">Минусы промисов <a class="header-anchor" href="#минусы-промисов" aria-label="Permalink to &quot;Минусы промисов&quot;">​</a></h3><ul><li>Нельзя отменить</li><li>Метод finally не особо кроссбраузерный</li></ul><h3 id="использование-метода-finally" tabindex="-1">Использование метода finally <a class="header-anchor" href="#использование-метода-finally" aria-label="Permalink to &quot;Использование метода finally&quot;">​</a></h3><ul><li>finally не меняет состояние промиса</li><li>Пример использования: скрыть лоадер (неважно ошибка или успешно)</li></ul><h3 id="комментарии" tabindex="-1">Комментарии <a class="header-anchor" href="#комментарии" aria-label="Permalink to &quot;Комментарии&quot;">​</a></h3><ul><li>При взаимодействии с API catch используется для обработки http статусов 4xx 5xx, then это статусы 2xx</li><li>Состояние промиса изменяется 1 раз</li><li>Promise после reject/resolve - неизменны</li><li>Отсутствие внешнего catch не останавливает выполнение скрипта. Когда обработчик в промисах делает throw – в данном случае, при ошибке запроса, то такая ошибка не останавливает выполнение скрипта и не выводится в консоли. Она просто будет передана в ближайший следующий обработчик onRejected</li></ul>`,17)])])}const u=a(t,[["render",o]]);export{m as __pageData,u as default};
